let language;
try { language = localStorage.getItem('webpushLanguage'); } catch (_) {}
const requestedLanguage=new URL(location.href).searchParams.get('lang');
if(['de','en'].includes(requestedLanguage))language=requestedLanguage;
if (!['de','en'].includes(language)) language = navigator.language?.toLowerCase().startsWith('de') ? 'de' : 'en';
function locale(){return language === 'de' ? 'de-DE' : 'en-GB'}
function t(value){return language === 'en' ? translations[value] || value : value}
function translateStatic(){
 document.documentElement.lang=language;
 const walker=document.createTreeWalker(document.documentElement,NodeFilter.SHOW_TEXT);
 const texts=[];while(walker.nextNode()){const node=walker.currentNode;if(!['SCRIPT','STYLE'].includes(node.parentElement?.tagName)&&translations[node.textContent.trim()])texts.push([node,node.textContent]);}
 for(const [node,source] of texts)node.textContent=source.replace(source.trim(),t(source.trim()));
 for(const element of document.querySelectorAll('[placeholder]'))element.placeholder=t(element.placeholder);
 for(const element of document.querySelectorAll('[title],[aria-label]'))for(const attribute of ['title','aria-label']){const value=element.getAttribute(attribute);if(value)element.setAttribute(attribute,t(value));}
 // Only localize the initial suggested device name; user input is never translated.
 const device=document.getElementById('deviceName');if(device.value==='Mein Gerät')device.value=t('Mein Gerät');
 document.getElementById('language').value=language;
}
translateStatic();
function applyLanguage(value){
 if(!['de','en'].includes(value))return;
 try { localStorage.setItem('webpushLanguage',value); } catch (_) {}
 const url=new URL(location.href);url.searchParams.set('lang',value);location.replace(url);
}
document.getElementById('language').addEventListener('change',event=>setUiLanguage(event.target.value).catch(error=>{status(error.message,true);event.target.value=language}));
